    for k, vi, en in [('cough', 'ho', 'cough'), ('coughfever', 'ho, sốt', 'cough, fever'), ('none', 'không', 'none'), ('peni', 'penicillin (nặng)', 'penicillin (severe)'),
                      ('empty', '(trống)', '(empty)'), ('late', 'đến muộn 10 phút', 'arriving 10 min late'), ('pm', 'xin đổi sang buổi chiều', 'please move me to the afternoon'),
                      ('both', 'đến muộn 10 phút; xin đổi sang buổi chiều', 'arriving 10 min late; please move me to the afternoon')]:
        z('cf.v.' + k, vi, en)
    z('cf.mk.lost', 'thay đổi bị mất', 'change lost'); z('cf.mk.conflict', 'xung đột', 'conflict')
    z('cf.legend', 'Viền cam: bước hiện tại, hay trường máy đó đã sửa. Gạch đỏ: thay đổi bị mất, hay xung đột đang chờ người dùng.', 'Orange outline: the current step, or a field that device edited. Red hatched: a lost change, or a conflict waiting for the user.')

    C = 'i8'
    a(C + '.title', 'Nhiều thiết bị và xung đột', 'Multiple devices and conflicts')
    a(C + '.essence', 'Mỗi thiết bị ghi được lúc mất mạng là một bản sao nhận ghi. Hai thiết bị sửa cùng bản ghi mà không thấy nhau là ghi đồng thời (concurrent): không bên nào biết bên kia lúc ghi, dù cách nhau mười phút.\nGhi sau thắng (LWW, last write wins: giữ lần ghi có giờ lớn nhất) chọn một bên và âm thầm bỏ bên kia; dùng giờ của máy thì còn tệ hơn khi đồng hồ lệch. Ghi có điều kiện (If-Match: "chỉ ghi nếu server vẫn ở đúng bản này", dựa trên ETag, một nhãn phiên bản) biến ghi đè thành lỗi 412 (mã HTTP "điều kiện không thỏa") để app làm lại thay đổi trên bản mới.\nGửi chỉ phần đã sửa cho phép gộp theo trường; chỉ khi cùng một trường bị sửa khác nhau mới cần người dùng chọn.',
      'Every device that can write while offline is a copy that accepts writes. Two devices editing one record without seeing each other are concurrent writes: neither knew of the other when it wrote, even ten minutes apart.\nLast write wins (LWW: keep the write with the greatest time) picks one side and silently drops the other; using device clocks is worse when clocks drift. A conditional write (If-Match: "write only if the server is still at this exact version", based on an ETag, a version label) turns the overwrite into a 412 (the HTTP code for "condition not met") so the app redoes its change on the new version.\nSending only the edit allows per-field merging; only the same field edited two ways needs the user to choose.')
    a(C + '.goal.g1', 'Đã thấy lần ghi của điện thoại tới server', 'Saw the phone\'s write reach the server')
    a(C + '.goal.g2', 'Đã thấy bản ghi cuối cùng', 'Saw the final record')
    a(C + '.sim.sysdesign.conflict', 'ghi sau thắng, If-Match, gộp theo trường, cùng một trường', 'last write wins, If-Match, per-field merge, same field')

    S_ = 'hook'
    a(C + '.sec.%s.title' % S_, 'Đoán trước khi đọc', 'Predict before reading')
    a(C + '.sec.%s.badge' % S_, 'stable')
    B(C, S_, 1, 'predict', 'App lưu hồ sơ bằng PUT cả bản ghi; server giữ bản có giờ sửa mới nhất. Người dùng thêm dị ứng trên máy tính bảng lúc 10:02, rồi sửa triệu chứng trên điện thoại đang mất mạng lúc 10:05. Điện thoại có mạng lại lúc 10:20. Hồ sơ cuối cùng có dị ứng không?',
      'The app saves the form by PUTting the whole record; the server keeps the copy with the latest edit time. The user adds an allergy on the tablet at 10:02, then edits the symptoms on the offline phone at 10:05. The phone is back online at 10:20. Does the final form still have the allergy?')
    B(C, S_, 1, 'ans', 'Không. Điện thoại sửa trên bản v1 chưa có dị ứng và gửi cả bản ghi; giờ 10:05 lớn hơn nên server lấy bản đó. Dị ứng mất trên mọi máy mà không có lỗi nào. [[src:book-ddia2]]',
      'No. The phone edited v1, which had no allergy, and sent the whole record; 10:05 is later, so the server took it. The allergy is gone everywhere with no error. [[src:book-ddia2]]')

    S_ = 'concurrent'
    a(C + '.sec.%s.title' % S_, 'Mỗi thiết bị là một bản sao nhận ghi', 'Every device is a copy that accepts writes')
    a(C + '.sec.%s.badge' % S_, 'stable')
    B(C, S_, 1, 'p', 'Hồ sơ trước khám phải xem và sửa được bất kỳ lúc nào, kể cả khi mất mạng; lịch trên điện thoại và laptop cũng vậy. Khi đó mỗi thiết bị có một bản sao database nhận ghi (người ta gọi nó là một leader, tức nơi nhận ghi), và đồng bộ giữa các thiết bị là sao chép nhiều leader: mỗi bản sao tự nhận ghi, rồi gửi cho nhau bất đồng bộ (không chờ nhau), có thể trễ hàng giờ hay hàng ngày. Mạng giữa các thiết bị thì rất không tin cậy. [[src:book-ddia2]]',
      'The pre-visit form must be viewable and editable at any time, even offline; so must a calendar on a phone and a laptop. Then each device holds a database copy that accepts writes (called a leader, a place that takes writes), and syncing between devices is multi-leader replication: each copy takes writes on its own and sends them to the others asynchronously (without waiting), lagging hours or days. The network between devices is extremely unreliable. [[src:book-ddia2]]')
    B(C, S_, 2, 'p', 'Hai lần ghi là đồng thời khi không bên nào biết bên kia lúc ghi; không cần xảy ra cùng một lúc. Vì vậy chuyện này không chỉ của app offline-first (app dùng được cả khi mất mạng) như ở chương "Offline-first và đồng bộ nền" (H7) của track Lưu dữ liệu trên Android: một tab mở lâu trên máy tính bảng, gửi lại bản đã tải từ sáng, cũng là ghi đồng thời. [[src:book-ddia2]]',
      'Two writes are concurrent when neither was aware of the other when made; they need not happen at the same moment. So this is not only about offline-first apps (apps that keep working without a network) as in the chapter "Offline-first and background sync" (H7) of the Saving Data on Android track: a tab left open on a tablet, sending back a copy loaded that morning, is also a concurrent write. [[src:book-ddia2]]')

    S_ = 'lww'
    a(C + '.sec.%s.title' % S_, 'Ghi sau thắng: một bên âm thầm mất', 'Last write wins: one side silently lost')
    a(C + '.sec.%s.badge' % S_, 'stable')
    B(C, S_, 1, 'p', 'Cách đơn giản nhất là gắn giờ vào mỗi lần ghi và giữ bản có giờ lớn nhất. Martin Kleppmann nói tên gọi gây hiểu lầm: với hai lần ghi đồng thời, "sau" không xác định, nên thứ tự theo giờ gần như ngẫu nhiên. Ý nghĩa thật là chọn một bên thắng và âm thầm bỏ các bên khác, dù chúng đã được xử lý thành công. Chấp nhận được khi chỉ thêm bản ghi mới với khóa duy nhất (mã định danh không trùng) và không bao giờ sửa. [[src:book-ddia2]]',
      'The simplest way is to timestamp every write and keep the one with the greatest time. Martin Kleppmann says the name misleads: for concurrent writes "last" is undefined, so their time order is essentially random. What it really means is one side wins and the others are silently discarded, even though they were processed successfully. It is fine when you only insert records with unique keys (identifiers that never repeat) and never update. [[src:book-ddia2]]')
    B(C, S_, 2, 'p', 'Trên mobile còn thêm chuyện giờ do máy đặt. Nếu LWW dùng giờ của client (giờ do chính thiết bị đặt), máy có đồng hồ chạy nhanh sẽ thắng cả những lần ghi thật sự xảy ra sau, và dữ liệu bị bỏ mà không có lỗi. Người dùng chỉnh giờ điện thoại, hay pin hết làm giờ sai, là đủ. [[src:book-ddia2]]',
      'Mobile adds device-set clocks. If LWW uses client timestamps (times set by the user\'s own device), a device whose clock runs ahead beats even writes that truly happened later, and data is dropped without any error. A user changing the phone\'s clock, or a dead battery resetting it, is enough. [[src:book-ddia2]]')
    B(C, S_, 3, 'note', 'Gửi cả bản ghi khi chỉ sửa một trường là cách mời lost update vào: lần ghi mang theo giá trị cũ của mọi trường khác. Chu trình này gọi là đọc, sửa, ghi (read-modify-write). [[src:book-ddia2]]',
      'Sending the whole record when only one field changed invites lost updates: the write carries old values for every other field. This is called the read-modify-write cycle. [[src:book-ddia2]]')
    B(C, S_, 3, 'kind', 'pitfall')

    S_ = 'conditional'
    a(C + '.sec.%s.title' % S_, 'Ghi có điều kiện: If-Match và 412', 'Conditional writes: If-Match and 412')
    a(C + '.sec.%s.badge' % S_, 'stable')
    B(C, S_, 1, 'p', 'Theo RFC 9110, If-Match làm cho request có điều kiện: chỉ thực hiện nếu ETag hiện tại khớp, và phải khớp tuyệt đối (so sánh mạnh, ETag yếu có tiền tố W/ không được tính). Nó dùng nhiều nhất với PUT, POST, DELETE để tránh ghi đè khi nhiều client cùng sửa, tức vấn đề lost update. Điều kiện sai thì server không được thực hiện; thường trả 412 Precondition Failed ("điều kiện tiên quyết không thỏa"). Nếu server thấy thay đổi đó thật ra đã được áp dụng, RFC cho phép trả 2xx (nhóm mã thành công). [[src:rfc9110]]',
      'Per RFC 9110, If-Match makes the request conditional: perform it only if the current ETag matches, and it must match exactly (strong comparison; weak ETags prefixed W/ do not count). It is mostly used with PUT, POST, DELETE to prevent overwrites when several clients edit in parallel, the lost update problem. If the condition is false the server must not perform the method; it usually answers 412 Precondition Failed ("precondition failed"). If the server can tell the change was in fact already applied, the RFC allows a 2xx (any success code). [[src:rfc9110]]')
    B(C, S_, 2, 'p', 'Đây là ghi có điều kiện, hay khóa lạc quan khi so số phiên bản: không khớp thì lần ghi không có tác dụng, và chu trình đọc, sửa, ghi phải chạy lại. RFC không nói client làm gì sau 412; theo site, cách hợp lý là tải bản mới rồi áp lại ý định của người dùng ("đổi triệu chứng thành ho, sốt"), không gửi lại bản đã sửa trên v1. Server có thể đòi mọi lần ghi phải có điều kiện bằng 428 Precondition Required, nhưng RFC 6585 (văn bản bổ sung vài mã trạng thái HTTP) nói mã này là tùy chọn. [[src:book-ddia2]] [[src:rfc6585]]',
      'This is a conditional write, or optimistic locking when comparing version numbers: if it does not match the write has no effect and the read-modify-write cycle runs again. The RFC does not say what the client does after a 412; in the site\'s view, the sensible move is to fetch the new version and reapply the user\'s intent ("set symptoms to cough, fever"), not resend the copy edited on v1. A server can demand that every write be conditional with 428 Precondition Required, but RFC 6585 (a document adding a few HTTP status codes) says that code is optional. [[src:book-ddia2]] [[src:rfc6585]]')
    B(C, S_, 3, 'kt', 'PUT /forms/42\nIf-Match: "v1"\n← 412 Precondition Failed          (server đang ở "v2", không ghi gì)\n\nGET /forms/42\n← 200, ETag: "v2"\nPUT /forms/42                        (làm lại thay đổi trên v2)\nIf-Match: "v2"\n← 200, ETag: "v3"',
      'PUT /forms/42\nIf-Match: "v1"\n← 412 Precondition Failed          (the server is at "v2", nothing written)\n\nGET /forms/42\n← 200, ETag: "v2"\nPUT /forms/42                        (redo the change on v2)\nIf-Match: "v2"\n← 200, ETag: "v3"')

    S_ = 'merge'
    a(C + '.sec.%s.title' % S_, 'Gộp theo trường, và khi nào phải hỏi người dùng', 'Per-field merging, and when to ask the user')
    a(C + '.sec.%s.badge' % S_, 'stable')
    B(C, S_, 1, 'p', 'Khi xung đột không tránh được có ba hướng: LWW; giữ mọi giá trị đồng thời (siblings, "các bản anh em") để ứng dụng hay người dùng tự gộp; và gộp tự động bằng thuật toán hợp với loại dữ liệu. Với map khóa-giá trị (mỗi tên trường là một khóa), cập nhật vào các khóa khác nhau được xử lý độc lập. Hồ sơ là một map như vậy: gửi bản gốc cùng các trường đã đổi thì server gộp được từng trường. [[src:book-ddia2]]',
      'When conflicts cannot be avoided there are three directions: LWW; keeping every concurrent value (siblings) for the application or the user to merge; and automatic merging with an algorithm suited to the data type. For a key-value map (each field name is a key), updates to different keys are handled independently. The form is such a map: send the base version with the changed fields, and the server can merge field by field. [[src:book-ddia2]]')
    B(C, S_, 2, 'p', 'Khi cùng một trường bị sửa khác nhau, Alex Xu mô tả cách của một dịch vụ lưu tệp: bản tới trước thắng, bản tới sau nhận xung đột, và app hiện cả bản trên máy lẫn bản mới nhất để người dùng gộp hay chọn. Martin Kleppmann cảnh báo hai điều: bắt người dùng gộp tốn công cho cả người viết app lẫn người dùng, và gộp tự động bất cẩn gây bất ngờ. Ví dụ giỏ hàng: máy A xóa món X, máy B (chưa thấy việc xóa) thêm món Y. Nếu gộp theo hợp tập hợp (giữ mọi món có ở bất kỳ bản nào) thì món X đã xóa hiện lại, vì bản của B vẫn còn X. [[src:book-xu1]] [[src:book-ddia2]]',
      'When the same field is changed two ways, Alex Xu describes a file service: the version that arrives first wins, the later one gets a conflict, and the app shows both the local copy and the latest one for the user to merge or pick. Martin Kleppmann warns of two things: making users merge costs effort for both developers and users, and careless automatic merging surprises people. Take a shopping cart: device A removes item X, device B (which has not seen the removal) adds item Y. If the merge is a set union (keep every item present in any copy), the removed X comes back, because B\'s copy still has X. [[src:book-xu1]] [[src:book-ddia2]]')
    B(C, S_, 3, 'note', 'Danh sách và văn bản dài (ghi chú nhiều đoạn, danh sách thuốc) không gộp được bằng quy tắc theo trường. CRDT (kiểu dữ liệu tự gộp được mọi bản sao) và OT (cách biến đổi thao tác của nhiều người để khớp nhau, dùng khi soạn thảo chung) sinh ra cho các loại này; chương không đi sâu. Gợi ý của site: bắt đầu bằng If-Match cho mọi lần ghi, rồi gộp theo trường cho những màn có nhiều trường độc lập.',
      'Lists and long text (multi-paragraph notes, medication lists) cannot be merged by per-field rules. CRDTs (data types whose copies merge automatically) and OT (operational transformation: adjusting each person\'s operations so they fit together, used in shared editing) were made for these; this chapter does not go deeper. The site\'s suggestion: start with If-Match on every write, then per-field merging for screens with many independent fields.')
    B(C, S_, 3, 'kind', 'android')

    S_ = 'bugs'
    a(C + '.sec.%s.title' % S_, 'Hai lỗi hay gặp', 'Two common bugs')
    a(C + '.sec.%s.badge' % S_, 'stable')
    B(C, S_, 1, 'bug', 'Sau khi thêm If-Match, app rơi vào vòng 412 liên tục và người dùng không lưu được.', 'After adding If-Match, the app loops on 412 and the user cannot save.')
    B(C, S_, 1, 'cause', 'Sau 412, app tải bản mới nhưng gửi lại bản đã sửa trên v1 với ETag mới; hoặc gửi lại ETag cũ mà không tải lại.', 'After a 412 the app fetches the new version but resends the copy edited on v1 with the new ETag; or resends the old ETag without fetching.')
    B(C, S_, 1, 'fix', 'Lưu ý định (các trường đã đổi), áp lại lên bản mới rồi gửi với ETag mới; giới hạn số lần thử và hỏi người dùng nếu vẫn xung đột.', 'Keep the intent (the changed fields), reapply it to the new version and send with the new ETag; cap the retries and ask the user if it still conflicts.')
    B(C, S_, 2, 'bug', 'Người dùng đổi giờ điện thoại về hôm qua; mọi thay đổi trên điện thoại sau đó đều "biến mất".', 'A user sets the phone\'s clock back a day; every edit on the phone afterwards "disappears".')
    B(C, S_, 2, 'cause', 'Server chọn bản theo editedAt (trường ghi giờ sửa) do điện thoại đặt (LWW theo giờ client); bản của điện thoại luôn có giờ nhỏ hơn bản đang lưu.', 'The server picks by the phone-set editedAt (the field holding the edit time; LWW on client clocks); the phone\'s copies always look older than the stored one.')
    B(C, S_, 2, 'fix', 'Không dùng giờ client để phân xử; dùng số phiên bản do server cấp (ETag) và ghi có điều kiện. [[src:book-ddia2]]', 'Never arbitrate with client clocks; use server-issued versions (ETags) and conditional writes. [[src:book-ddia2]]')

    S_ = 'ex'
    a(C + '.sec.%s.title' % S_, 'Bài tập', 'Exercise')
    a(C + '.sec.%s.badge' % S_, 'guideline')
    B(C, S_, 1, 'ex', 'Hồ sơ có thêm trường "thuốc đang dùng" là một danh sách, bản gốc v1 là {aspirin}. Máy tính bảng xóa "aspirin", điện thoại (mất mạng, gốc v1) thêm "vitamin D". (a) Gộp theo trường coi cả danh sách là một giá trị thì chuyện gì xảy ra? (b) Gộp bằng hợp tập hợp thì sao? (c) Cách nào cho kết quả đúng?',
      'The form gains a "current medications" field that is a list, with v1 being {aspirin}. The tablet removes "aspirin"; the phone (offline, base v1) adds "vitamin D". (a) What happens if per-field merging treats the whole list as one value? (b) What about merging by set union? (c) What gives the right result?')
    B(C, S_, 1, 'hint', 'Xem lại ví dụ giỏ hàng ở mục gộp theo trường phía trên.', 'Revisit the shopping cart example in the per-field merging section above.')
    B(C, S_, 1, 'sol', '(a) Cả hai bên đều đổi trường đó nên thành xung đột, phải hỏi người dùng. (b) Hợp tập hợp cho {aspirin, vitamin D}: aspirin đã xóa hiện lại, đúng như lỗi giỏ hàng ở mục gộp theo trường. (c) Gửi thao tác thay vì cả danh sách: "xóa aspirin", "thêm vitamin D"; server áp cả hai và ghi nhớ việc xóa, cho {vitamin D}. Đó là ý tưởng của CRDT cho tập hợp. [[src:book-ddia2]]',
      '(a) Both sides changed the field, so it is a conflict and the user must decide. (b) Set union gives {aspirin, vitamin D}: the removed aspirin comes back, exactly the cart bug described in the per-field merging section. (c) Send operations instead of the whole list: "remove aspirin", "add vitamin D"; the server applies both and remembers the removal, giving {vitamin D}. That is the idea behind set CRDTs. [[src:book-ddia2]]')

    for q, qv, qe, av, ae, wv, we in [
        ('q1', 'Hai lần ghi cách nhau 15 phút có thể là "đồng thời" không?', 'Can two writes 15 minutes apart be "concurrent"?', 'Có, nếu không bên nào biết bên kia lúc ghi, ví dụ một máy đang mất mạng.', 'Yes, if neither knew of the other when written, for example one device was offline.', 'Đồng thời là về hiểu biết, không phải về giờ.', 'Concurrency is about awareness, not the clock.'),
        ('q2', 'Server trả 412 cho PUT kèm If-Match. Dữ liệu trên server đã đổi chưa?', 'The server answers 412 to a PUT with If-Match. Did the server data change?', 'Chưa. Điều kiện sai thì server không thực hiện request.', 'No. With a false condition the server does not perform the request.', 'App cần tải bản mới và làm lại thay đổi.', 'The app needs to fetch the new version and redo its change.'),
        ('q3', 'Vì sao gửi chỉ các trường đã sửa giúp tránh mất dữ liệu?', 'Why does sending only the edited fields help avoid data loss?', 'Lần ghi không mang theo giá trị cũ của các trường khác, nên không đè lên thay đổi của máy khác; server còn gộp được từng trường.', 'The write carries no old values for other fields, so it cannot clobber another device\'s change; and the server can merge per field.', 'Gửi cả bản ghi là chu trình đọc, sửa, ghi dễ gây lost update.', 'Sending the whole record is a read-modify-write cycle prone to lost updates.'),
        ('q4', 'Vì sao không nên dùng giờ của điện thoại để quyết định bản nào thắng?', 'Why should the phone\'s clock not decide which copy wins?', 'Đồng hồ thiết bị có thể sai hay bị chỉnh; máy có giờ chạy nhanh sẽ thắng cả những lần ghi xảy ra sau, và dữ liệu mất không báo lỗi.', 'Device clocks can be wrong or changed; a device running ahead beats even later writes, and data is lost without an error.', 'Dùng phiên bản do server cấp.', 'Use server-issued versions.')]:
        a(C + '.quiz.%s.q' % q, qv, qe); a(C + '.quiz.%s.a' % q, av, ae); a(C + '.quiz.%s.why' % q, wv, we)
